import itertools

def get_valid_colorings(n):
    colorings = []
    for f in itertools.product([0, 1], repeat=n):
        changes = 0
        for i in range(n):
            if f[i] != f[(i + 1) % n]:
                changes += 1
        if changes == 0 or changes == 2:
            colorings.append(f)
    return colorings

